#!/usr/bin/env bash
# Build a Noctalia-tinted copy of Slot Beauty Dark Icons and select it.
#
# The original pack is never modified: a sibling theme is assembled from
# symlinks, and only the colourful folder icons under places/ are rewritten so
# the folder body lands exactly on Noctalia's `primary` colour.
# This section has been AI-generated by DeepSeek V4.1 Flash Free on 25.11.2026
# (rewritten from the Gemini 3.8 Flash version of the same hook).
set -euo pipefail

CONFIG_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
DATA_HOME="${XDG_DATA_HOME:-$HOME/.local/share}"
CONFIG_HOME="${XDG_CONFIG_HOME:-$HOME/.config}"
SRC="${SLOT_BEAUTY_SRC:-}"

# shellcheck source=ini.sh
source "$CONFIG_DIR/ini.sh"

if [[ -z "$SRC" ]]; then
  search_dirs=("$DATA_HOME" "$HOME/.icons")
  if [[ -n "${XDG_DATA_DIRS:-}" ]]; then
    IFS=: read -ra xdg_dirs <<< "$XDG_DATA_DIRS"
    search_dirs+=("${xdg_dirs[@]}")
  fi
  search_dirs+=(/usr/local/share /usr/share)

  for dir in "${search_dirs[@]}"; do
    [[ -n "$dir" ]] || continue
    cand="$dir/icons/Slot-Beauty-Dark-Icons-V-2"
    if [[ -d "$cand/places" ]]; then
      SRC="$cand"
      break
    fi
    cand="$dir/Slot-Beauty-Dark-Icons-V-2"
    if [[ -d "$cand/places" ]]; then
      SRC="$cand"
      break
    fi
  done
  SRC="${SRC:-$DATA_HOME/icons/Slot-Beauty-Dark-Icons-V-2}"
fi

DEST="$DATA_HOME/icons/Slot-Beauty-Dark-Icons-V-2-Noctalia"
STATE="$CONFIG_HOME/noctalia/slot-beauty-icons.state"
COLOR_FILE="$CONFIG_DIR/colors-final"
THEME_NAME="Slot-Beauty-Dark-Icons-V-2-Noctalia"

# ---------------------------------------------------------------- target ----

if [[ ! -f "$COLOR_FILE" ]]; then
  echo "Error: colors-final not found at $COLOR_FILE" >&2
  exit 1
fi

TARGET="$(head -n1 "$COLOR_FILE" | tr -d '[:space:]#')"
TARGET="${TARGET:0:6}"
if [[ ! "$TARGET" =~ ^[0-9a-fA-F]{6}$ ]]; then
  echo "Error: colors-final holds no valid hex colour: '$TARGET'" >&2
  exit 1
fi
TARGET="$(printf '%s' "$TARGET" | tr 'A-F' 'a-f')"

if [[ ! -d "$SRC/places" ]]; then
  echo "Error: Slot Beauty Dark Icons not found at $SRC" >&2
  exit 1
fi
SRC="$(readlink -f "$SRC")"

# ------------------------------------------------------------ build theme ----

# The stamp records everything the sync depends on: the target colour, the
# source pack, the generated theme itself, and the scripts that build it.
# Comparing all four means an icon-pack update, a template edit, or a damaged
# derived theme all trigger a rebuild, while a plain re-run stays free.
STAMP="$DEST/.noctalia-color"

# A fast metadata fingerprint (path, type, size, mtime, link target) is enough
# to notice a changed pack or a stray file; hashing every icon would be slow.
tree_signature() { # <dir>
  find "$1" -mindepth 1 \
    \( -name '.noctalia-color' -o -name '.noctalia-color.*' \
       -o -name '.icon-theme.cache' -o -name '.tmp-*' \) -prune -o \
    -printf '%P\t%y\t%s\t%T@\t%l\n' 2>/dev/null |
    LC_ALL=C sort |
    md5sum | cut -d' ' -f1
}

template_signature() {
  local files=("$CONFIG_DIR/recolor.py")
  [[ -f "$CONFIG_DIR/bodies.tsv" ]] && files+=("$CONFIG_DIR/bodies.tsv")
  cat -- "${files[@]}" | md5sum | cut -d' ' -f1
}

stamp_value() { # <file> <key>
  [[ -f "$1" ]] || return 0
  sed -n "s/^$2=//p" "$1" | head -n1
}

SRC_SIG="$(tree_signature "$SRC")"
TPL_SIG="$(template_signature)"

needs_sync=1
if [[ -f "$STAMP" && -f "$DEST/index.theme" && -d "$DEST/places" ]] \
   && [[ "$(stamp_value "$STAMP" target)" == "$TARGET" ]] \
   && [[ "$(stamp_value "$STAMP" source)" == "$SRC_SIG" ]] \
   && [[ "$(stamp_value "$STAMP" template)" == "$TPL_SIG" ]]; then
  # Only pay for the destination scan when everything else still matches.
  if [[ "$(stamp_value "$STAMP" dest)" == "$(tree_signature "$DEST")" ]]; then
    needs_sync=0
  fi
fi

if (( needs_sync )); then
  python3 "$CONFIG_DIR/recolor.py" sync "$TARGET" "$SRC" "$DEST" \
    --bodies "$CONFIG_DIR/bodies.tsv"

  # Record the post-sync state so the next run can trust the stamp.
  tmp_stamp="$STAMP.tmp.$$"
  trap 'rm -f -- "${tmp_stamp:-}"' EXIT INT TERM
  {
    printf 'target=%s\n' "$TARGET"
    printf 'source=%s\n' "$SRC_SIG"
    printf 'dest=%s\n' "$(tree_signature "$DEST")"
    printf 'template=%s\n' "$TPL_SIG"
  } > "$tmp_stamp"
  mv -f -- "$tmp_stamp" "$STAMP"
  trap - EXIT INT TERM
fi

# ----------------------------------------------------------- theme switch ----

# remember <key> <value>
# First value wins: repeated applies must keep the value that was active
# before the template touched anything, so undo can put it back.
remember() {
  mkdir -p -- "$(dirname -- "$STATE")"
  [[ -f "$STATE" ]] || : > "$STATE"
  grep -qE "^$1=" "$STATE" || printf '%s=%s\n' "$1" "$2" >> "$STATE"
}

# 1. GSettings (GNOME / Cinnamon / budgie / sway / niri / hyprland)
if command -v gsettings >/dev/null 2>&1; then
  if current_gsettings="$(gsettings get org.gnome.desktop.interface icon-theme 2>/dev/null)"; then
    current_gsettings="$(ini_unquote "$current_gsettings")"
    if [[ "$current_gsettings" != "$THEME_NAME" ]]; then
      # No dconf override means the value comes from a default: reset on undo
      # rather than pinning that default explicitly.
      previous="__RESET__"
      if command -v dconf >/dev/null 2>&1 \
         && [[ -n "$(dconf read /org/gnome/desktop/interface/icon-theme 2>/dev/null)" ]]; then
        previous="$current_gsettings"
      fi
      # Record only after the write succeeded, otherwise undo would "restore"
      # a value the desktop never had.
      if gsettings set org.gnome.desktop.interface icon-theme "'$THEME_NAME'" 2>/dev/null; then
        remember gsettings "$previous"
      else
        echo "Warning: could not set the GSettings icon theme; leaving it unchanged." >&2
      fi
    fi
  fi
fi

# 2. GTK 3
GTK3="$CONFIG_HOME/gtk-3.0/settings.ini"
if [[ -f "$GTK3" ]]; then
  current_gtk3="$(ini_get "$GTK3" Settings gtk-icon-theme-name)"
  if [[ "$current_gtk3" != "$THEME_NAME" ]]; then
    remember gtk3 "${current_gtk3:-__UNSET__}"
    ini_set "$GTK3" Settings gtk-icon-theme-name "$THEME_NAME"
  fi
else
  remember gtk3 "__UNSET__"
  remember gtk3_created "1"
  ini_set "$GTK3" Settings gtk-icon-theme-name "$THEME_NAME"
fi

# 3. GTK 4
GTK4="$CONFIG_HOME/gtk-4.0/settings.ini"
if [[ -f "$GTK4" ]]; then
  current_gtk4="$(ini_get "$GTK4" Settings gtk-icon-theme-name)"
  if [[ "$current_gtk4" != "$THEME_NAME" ]]; then
    remember gtk4 "${current_gtk4:-__UNSET__}"
    ini_set "$GTK4" Settings gtk-icon-theme-name "$THEME_NAME"
  fi
else
  remember gtk4 "__UNSET__"
  remember gtk4_created "1"
  ini_set "$GTK4" Settings gtk-icon-theme-name "$THEME_NAME"
fi

# 4. Qt5ct / Qt6ct (only update if existing config is present)
QT5="$CONFIG_HOME/qt5ct/qt5ct.conf"
if [[ -f "$QT5" ]]; then
  current_qt5="$(ini_get "$QT5" Appearance icon_theme)"
  if [[ "$current_qt5" != "$THEME_NAME" ]]; then
    remember qt5 "${current_qt5:-__UNSET__}"
    ini_set "$QT5" Appearance icon_theme "$THEME_NAME"
  fi
fi

QT6="$CONFIG_HOME/qt6ct/qt6ct.conf"
if [[ -f "$QT6" ]]; then
  current_qt6="$(ini_get "$QT6" Appearance icon_theme)"
  if [[ "$current_qt6" != "$THEME_NAME" ]]; then
    remember qt6 "${current_qt6:-__UNSET__}"
    ini_set "$QT6" Appearance icon_theme "$THEME_NAME"
  fi
fi

exit 0
# End of AI-generated section.
